const allowedRecovery = new Set(['resume_required', 'coverage_gap', 'resume_ready']);
const out = [];
for (const item of $input.all()) {
  const stdout = item.json.stdout;
  if (typeof stdout !== 'string' || !stdout.trim()) {
    throw new Error('P6 runner returned no JSON result');
  }
  let result;
  try { result = JSON.parse(stdout.trim()); }
  catch { throw new Error('P6 runner returned invalid JSON'); }
  const committed = Number.isInteger(result.committed_pages) && result.committed_pages >= 0
    ? result.committed_pages : null;
  const knownWait = ['WAIT_EXPLICIT_LIVE_APPROVAL', 'SKIP_CONCURRENT'].includes(result.action);
  const failures = Number.isInteger(result.account_failures) && result.account_failures >= 0
    ? result.account_failures : knownWait ? 0 : null;
  const recoveryValue = result.recovery_status || result.status;
  const recovery = allowedRecovery.has(recoveryValue) ? recoveryValue : null;
  const completed = result.action === 'LIVE_TICK_COMPLETE';
  const malformed = committed === null || failures === null || typeof result.action !== 'string';
  const state = malformed ? 'manual_review'
    : recovery ? 'attention'
    : failures > 0 ? 'attention'
    : completed && committed > 0 ? 'collection_progress'
    : knownWait || completed ? 'waiting' : 'manual_review';
  out.push({json: {
    state, action: result.action || 'unknown',
    run_status: typeof result.status === 'string' ? result.status : null,
    committed_pages: committed, account_failures: failures,
    max_pages: Number.isInteger(result.max_pages) ? result.max_pages : null,
    live_meta_called: result.live_meta_called === true,
    recovery_status: recovery,
    alert_required: state === 'attention' || state === 'manual_review',
    alert_code: recovery || (failures > 0 ? 'account_failures' : state)
  }});
}
return out;
